def build_workbook(
    path: Path,
    *,
    with_themes: bool = True,
    with_optional: bool = True,
    codes: list[list[str]] | None = None,
    questions: list[list[str]] | None = None,
    themes: list[list[str]] | None = None,
    extra_sheets: dict[str, list[list[str]]] | None = None,
) -> Path:
    """Собрать синтетическую книгу той же структуры, что рабочая книга проекта."""
    wb = Workbook()
    default = wb.active
    if default is not None:
        wb.remove(default)

    def add(name: str, rows: list[list[str]]) -> None:
        if name in wb.sheetnames:
            del wb[name]
        ws = wb.create_sheet(name)
        header = HEADERS.get(name) or [f"колонка_{i}" for i in range(1, max((len(r) for r in rows), default=0) + 1)]
        ws.append(header)
        for row in rows:
            ws.append(row)

    add("Вопросы_и_коды", questions if questions is not None else QUESTIONS)
    add("Коды", codes if codes is not None else CODES)
    add(
        "Атрибуты",
        [
            ["ГРУППА", "атрибут", "ТОРГ / не торгующие"],
            ["ПОНИМАНИЕ", "оценка", "Верно / неверно"],
            ["НАДЁЖНОСТЬ_КОДА", "оценка", "1–3, насколько код следует из текста"],
        ],
    )
    if with_optional:
        add("Словарь_замен", [["MCP, токен", "подключение ИИ к счёту"]])
        add(
            "Лексикон",
            [
                ["MCP", "эмсипи; эсипи", "протокол подключения", "предложен"],
                ["Финам", "Финанм", "название брокера", "предложен"],
            ],
        )
        add("Маркеры_неуверенности", [["не знаю", None], ["наверное", None]])
        add(
            "Интервью",
            [["R01", "R01", "не торгующие", "2026-11-02", "R01.txt", None, None]],
        )
        add("Роли_говорящих", [])
        add("Золотой_набор", [])
        add("Факты_Финам", [])
    if with_themes:
        add(
            "Темы",
            themes
            if themes is not None
            else [
                ["Риски", "Риски", "R1; R2", "черновик", "из семьи"],
                ["Риски", "Проверка", "V1", "черновик", "из семьи"],
                ["Риски", "Ошибки исполнения", "E0; E1", "черновик", "из семьи"],
                ["Ответственность", "Ответственность", "A1", "черновик", "из семьи"],
                ["Ответственность", "Основание", "B1", "черновик", "из семьи"],
                ["Ответственность", "Контроль", "C1", "черновик", "из семьи"],
                ["Предупреждения", "Предупреждения", "N1", "черновик", "из семьи"],
                ["Индуктивные", "Индуктивный", "OTH", "черновик", "из семьи"],
            ],
        )
    for name, rows in (extra_sheets or {}).items():
        add(name, rows)

    path.parent.mkdir(parents=True, exist_ok=True)
    wb.save(path)
    return path
